def get_all_approved_topics() -> List[Dict[str, Any]]:
    """Returns the complete verified list of approved topics."""
    return APPROVED_TOPICS

def get_topic_by_id(topic_id: int) -> Optional[Dict[str, Any]]:
    """Finds topic by its unique ID."""
    for t in APPROVED_TOPICS:
        if t.get("id") == topic_id:
            return t
    return None

def get_topics_by_category(category: str) -> List[Dict[str, Any]]:
    """Filters topics by category."""
    return [t for t in APPROVED_TOPICS if t.get("category") == category]

def search_approved_topics(query: str) -> List[Dict[str, Any]]:
    """Searches titles and intents for matching keywords."""
    q = query.lower()
    return [t for t in APPROVED_TOPICS if q in t.get("title", "").lower() or q in t.get("intent", "").lower()]
